<template>
  <div class="admin-list-page">
    <header class="page-head"><div><span class="eyebrow">运营中心 / 任务监控</span><h2>AI 任务中心</h2><p>监控生成任务状态、模型、用户和异常原因，方便处理上游超时与失败。</p></div><t-button variant="outline" :loading="loading" @click="load"><template #icon><t-icon name="refresh" /></template>刷新</t-button></header>
    <section class="state-row"><button v-for="item in stateCards" :key="item.value" :class="['state-card',{active:state===item.value}]" @click="state=item.value;refresh()"><strong>{{ item.count }}</strong><span>{{ item.label }}</span></button></section>
    <section class="panel"><div class="toolbar"><t-input v-model="search" clearable placeholder="用户 / 模型 / 任务类型" style="width:260px" @enter="refresh" /><t-select v-model="state" clearable placeholder="全部状态" style="width:170px" @change="refresh"><t-option value="pending" label="等待中"/><t-option value="running" label="运行中"/><t-option value="processing" label="处理中"/><t-option value="success" label="成功"/><t-option value="failed" label="失败"/></t-select><t-button theme="primary" @click="refresh">查询</t-button></div><t-table :data="tasks" :columns="columns" :loading="loading" row-key="id" :hover="true"><template #id="{row}"><span class="mono">#{{row.id}}</span></template><template #user_name="{row}">{{row.user_name||"—"}}</template><template #state="{row}"><t-tag :theme="stateTheme(row.state)" variant="light">{{stateText(row.state)}}</t-tag></template><template #describe="{row}"><span class="desc" :title="row.describe">{{row.describe||"—"}}</span></template><template #startTime="{row}">{{formatTime(row.startTime)}}</template></t-table><div class="pager" v-if="pagination.total"><span>共 {{pagination.total}} 条</span><t-pagination v-model:current="pagination.page" v-model:pageSize="pagination.limit" :total="pagination.total" size="small" @change="load" /></div><t-empty v-if="!loading&&!tasks.length" description="暂无任务记录" /></section>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from "vue"; import axios from "@/utils/axios";
const loading=ref(false),search=ref(""),state=ref(""),tasks=ref<any[]>([]),stateStats=ref<any[]>([]);const pagination=reactive({page:1,limit:20,total:0});const columns=[{colKey:"id",title:"任务",width:80},{colKey:"user_name",title:"用户",width:130},{colKey:"taskClass",title:"任务类型",width:150},{colKey:"model",title:"模型",width:170},{colKey:"state",title:"状态",width:100},{colKey:"describe",title:"描述",minWidth:220},{colKey:"startTime",title:"开始时间",width:170}];const labels:Record<string,string>={pending:"等待中",running:"运行中",processing:"处理中",success:"成功",succeeded:"成功",failed:"失败",error:"失败"};const stateCards=computed(()=>[{value:"",label:"全部任务",count:stateStats.value.reduce((n,x)=>n+Number(x.count||0),0)},...["running","pending","success","failed"].map(value=>({value,label:labels[value],count:Number(stateStats.value.find(x=>x.state===value)?.count||0)}))]);
function stateText(v:string){return labels[v]||v||"未知"}function stateTheme(v:string){return ({running:"primary",pending:"warning",processing:"primary",success:"success",succeeded:"success",failed:"danger",error:"danger"} as any)[v]||"default"}function formatTime(v:any){if(!v)return"—";const d=new Date(Number(v)||v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString("zh-CN",{hour12:false})}function refresh(){pagination.page=1;load()}let requestVersion = 0;
onUnmounted(() => { requestVersion++; });
async function load(){const version = ++requestVersion;loading.value=true;try{const res=await axios.get("/admin/tasks",{params:{page:pagination.page,limit:pagination.limit,search:search.value,state:state.value}});if(version !== requestVersion)return;tasks.value=res.data?.tasks||[];stateStats.value=res.data?.stateStats||[];Object.assign(pagination,res.data?.pagination||{});}catch(e:any){if(version !== requestVersion)return;window.$message?.error?.(e.message||"任务加载失败")}finally{if(version === requestVersion)loading.value=false}}onMounted(load);
</script>
<style scoped lang="scss">
.admin-list-page{padding:28px 32px 38px;color:#152238}.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:22px}.eyebrow{font-size:11px;font-weight:750;letter-spacing:.12em;color:#ef6c35}.page-head h2{margin:8px 0 5px;font-size:25px}.page-head p{margin:0;color:#8993a5;font-size:13px}.state-row{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:18px}.state-card{padding:14px 16px;border:1px solid #e8ebf1;border-radius:14px;background:#fff;text-align:left;cursor:pointer}.state-card.active{border-color:#f2762e;background:#fff8f4}.state-card strong,.state-card span{display:block}.state-card strong{font-size:22px}.state-card span{margin-top:3px;color:#8993a5;font-size:11px}.panel{border:1px solid #e8ebf1;border-radius:17px;background:#fff;overflow:hidden}.toolbar{display:flex;gap:10px;align-items:center;padding:18px 20px;border-bottom:1px solid #eef0f4;flex-wrap:wrap}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:#536079}.desc{display:block;max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#657087}.pager{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-top:1px solid #eef0f4;color:#8a94a4;font-size:12px}@media(max-width:750px){.admin-list-page{padding:20px 15px}.page-head{align-items:flex-start;flex-direction:column}.state-row{grid-template-columns:repeat(2,1fr)}.panel{overflow:auto}.toolbar,.pager{min-width:800px}}
</style>
